import math

def select_next_node(graph, unvisited_nodes):
    pre = graph.graph['precomputed']
    unvisited_set = set(unvisited_nodes)

    # Pre-extract clustering for all nodes to avoid repeated lookups
    clustering = {n: graph.nodes[n]['clustering'] for n in unvisited_nodes}
    degree = {n: graph.nodes[n]['degree'] for n in unvisited_nodes}

    def local_entropy(node):
        neighbors = [nbr for nbr in graph.neighbors(node) if nbr in unvisited_set]
        if not neighbors:
            return 0.0
        degs = [degree[nbr] for nbr in neighbors]
        total = sum(degs)
        if total == 0:
            return 0.0
        probs = [d / total for d in degs]
        ent = -sum(p * math.log(p, 2) if p > 0 else 0 for p in probs)
        return ent  # entropy in bits

    scores = {}
    for node in unvisited_nodes:
        neighbors = [nbr for nbr in graph.neighbors(node) if nbr in unvisited_set]
        if not neighbors:
            scores[node] = 0.0
            continue

        # Sum of degrees weighted by inverse clustering of neighbors (avoid div0)
        weighted_sum = 0.0
        for nbr in neighbors:
            c = clustering[nbr]
            weight = 1.0 / (c + 0.01)  # small smoothing to avoid div0
            weighted_sum += degree[nbr] * weight

        ent = local_entropy(node)

        # Combine weighted neighbor connectivity and entropy with a harmonic mean to balance both
        if weighted_sum + ent > 0:
            score = 2 * weighted_sum * ent / (weighted_sum + ent)
        else:
            score = 0.0

        scores[node] = score

    next_node = max(scores, key=scores.get)
    return next_node
